begin;
create function pg_temp.assert_true(ok boolean,msg text) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'ASSERT: %',msg; end if; end $$;
create function pg_temp.expect_error(q text,states text[]) returns void language plpgsql as $$
begin
 begin execute q; exception when others then
 if sqlstate=any(states) then return; end if; raise; end;
 raise exception 'Expected rejection but succeeded: %',q;
end $$;

